from pathlib import Path

A = Path('buildsrc/NAR-Mix/app/src/main/assets')
js = A / 'app.js'
css = A / 'app.css'

s = js.read_text()
start = s.find('function age(){')
end = s.find('function app(){', start)
if start < 0 or end < 0:
    raise SystemExit('age/app hook missing')

new_age = r'''function age(){document.getElementById('app').innerHTML=`<div class="narLaunchV46" id="narLaunchEnter" role="button" tabindex="0" aria-label="Enter NĀR"><div class="launchGlow"></div><div class="launchSmoke launchSmokeA"></div><div class="launchSmoke launchSmokeB"></div><div class="launchWordmark"><div class="launchNar">NĀR</div><div class="launchSub">HOOKAH KNOWLEDGE · MIXOLOGY</div><div class="launchRule"></div><div class="launchSlogan">Knowledge tastes better.</div></div><div class="launchBowl" aria-hidden="true"><div class="launchEmbers"></div><div class="launchBowlBody"></div><div class="launchStem"></div></div><button class="launchEnter" id="enter">ENTER NĀR <span>→</span></button><div class="launchLegal">LEGAL SMOKING AGE ONLY · TOBACCO CARRIES HEALTH RISKS</div></div>`;const enter=()=>{state.age=true;save();app()};$('#enter').onclick=e=>{e.stopPropagation();enter()};$('#narLaunchEnter').onclick=enter;$('#narLaunchEnter').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();enter()}}}'''

s = s[:start] + new_age + '\n' + s[end:]
js.write_text(s)

c = css.read_text()
c += r'''

/* ===== NAR MIX 4.6 — SOPHISTICATED COVER LOCK ===== */
.narLaunchV46{position:relative;min-height:100dvh;box-sizing:border-box;overflow:hidden;background:radial-gradient(120% 75% at 100% 42%,rgba(118,57,18,.34) 0%,rgba(52,26,10,.18) 26%,transparent 60%),radial-gradient(90% 50% at 50% 100%,rgba(102,46,11,.18),transparent 70%),linear-gradient(180deg,#050403 0%,#080604 62%,#030302 100%);color:#f5dfbc;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:calc(var(--safe-top,0px) + 28px) 26px calc(var(--safe-bottom,0px) + 24px);isolation:isolate}.narLaunchV46:before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,rgba(0,0,0,.46),transparent 48%,rgba(0,0,0,.08)),radial-gradient(circle at 72% 70%,rgba(255,150,46,.09),transparent 26%);pointer-events:none;z-index:-1}.launchGlow{position:absolute;right:-18%;bottom:12%;width:70vw;height:52vw;border-radius:50%;background:radial-gradient(circle,rgba(223,128,37,.17),rgba(103,47,12,.07) 44%,transparent 72%);filter:blur(8px)}.launchWordmark{position:absolute;top:24%;left:50%;transform:translateX(-50%);width:min(88vw,620px);text-align:center;z-index:3}.launchNar{font-family:Georgia,'Times New Roman',serif;font-size:clamp(74px,22vw,150px);font-weight:500;letter-spacing:.08em;line-height:.9;background:linear-gradient(180deg,#f9d79b 0%,#d39a4a 52%,#f5c777 100%);-webkit-background-clip:text;background-clip:text;color:transparent;text-shadow:0 10px 34px rgba(179,93,23,.18)}.launchSub{margin-top:24px;font-size:clamp(10px,3vw,16px);letter-spacing:.27em;color:#e5c18b;white-space:nowrap}.launchRule{width:52px;height:1px;background:#c48a42;margin:38px auto 34px}.launchSlogan{font-family:Georgia,'Times New Roman',serif;font-size:clamp(18px,5vw,28px);letter-spacing:.13em;color:#e8d0aa}.launchSmoke{position:absolute;right:3%;bottom:27%;width:42vw;height:55vh;border-radius:50%;opacity:.26;filter:blur(10px);transform:rotate(-10deg);background:radial-gradient(ellipse at 40% 85%,rgba(231,154,77,.55),transparent 18%),radial-gradient(ellipse at 60% 62%,rgba(216,139,63,.36),transparent 17%),radial-gradient(ellipse at 45% 38%,rgba(226,156,86,.26),transparent 16%),radial-gradient(ellipse at 68% 14%,rgba(235,174,112,.20),transparent 13%);animation:narSmokeFloat 7s ease-in-out infinite alternate}.launchSmokeB{right:-9%;bottom:37%;opacity:.18;transform:scale(.78) rotate(14deg);animation-duration:9s}.launchBowl{position:absolute;right:-4vw;bottom:10%;width:min(62vw,380px);height:min(41vw,250px);z-index:2;filter:drop-shadow(0 28px 45px rgba(0,0,0,.65))}.launchEmbers{position:absolute;left:10%;right:2%;top:1%;height:31%;border-radius:50%;background:radial-gradient(circle at 25% 40%,#ffb34d 0 3%,transparent 4%),radial-gradient(circle at 48% 52%,#f06d22 0 4%,transparent 5%),radial-gradient(circle at 70% 30%,#ffca64 0 3%,transparent 4%),radial-gradient(circle at 82% 56%,#d84e16 0 4%,transparent 5%),radial-gradient(ellipse,#6d2d12 0%,#2d1209 42%,#130907 70%);box-shadow:0 0 28px rgba(233,105,24,.22)}.launchBowlBody{position:absolute;left:8%;right:0;top:18%;height:54%;background:linear-gradient(180deg,#221812,#070606 72%);border-radius:12% 12% 52% 52%/12% 12% 76% 76%;border-top:2px solid rgba(224,170,104,.26);box-shadow:inset 0 -22px 30px rgba(0,0,0,.7),inset 9px 0 20px rgba(122,74,38,.15)}.launchStem{position:absolute;right:19%;bottom:0;width:23%;height:43%;background:linear-gradient(90deg,#080706,#49301e 48%,#c38542 55%,#2e1d13 72%,#050504);clip-path:polygon(20% 0,80% 0,72% 100%,28% 100%)}.launchEnter{position:absolute;left:50%;bottom:8.5%;transform:translateX(-50%);width:min(72vw,460px);height:64px;border:0;border-radius:999px;background:linear-gradient(90deg,#f5c76e 0%,#d89b47 48%,#eab663 100%);color:#171008;font-family:Georgia,'Times New Roman',serif;font-size:clamp(18px,5vw,25px);letter-spacing:.19em;box-shadow:0 10px 34px rgba(181,97,29,.20);z-index:5}.launchEnter span{font-family:Arial,sans-serif;font-size:1.35em;margin-left:16px}.launchEnter:active{transform:translateX(-50%) scale(.985)}.launchLegal{position:absolute;bottom:calc(var(--safe-bottom,0px) + 6px);left:18px;right:18px;text-align:center;color:#71695f;font-size:7px;letter-spacing:.13em;z-index:5}@keyframes narSmokeFloat{from{transform:translate3d(0,12px,0) rotate(-10deg) scale(.97)}to{transform:translate3d(-8px,-12px,0) rotate(-5deg) scale(1.04)}}@media(max-height:720px){.launchWordmark{top:18%}.launchNar{font-size:74px}.launchSub{margin-top:15px}.launchRule{margin:22px auto 18px}.launchSlogan{font-size:18px}.launchBowl{bottom:14%;width:48vw}.launchEnter{height:56px;bottom:6.5%}}
'''
css.write_text(c)
print('Patched NAR Mix 4.6 sophisticated simple bold cover')
